// Master Aircraft Structures and Design Question Bank (Part 2: Items 51 to 185+)
// Source Materials: Answer Key 2016, Aircraft Structures Mock Exam, PRC Exam, Aircraft Structures Dry Run

window.ALL_AELE_QUESTIONS = window.ALL_AELE_QUESTIONS || [];

window.ALL_AELE_QUESTIONS.push(
  // SECTION 2: STRUCTURES & DESIGN REVIEW 2016 (ITEMS 51-100)
  {"id":"STRUC-051","subject":"Aircraft Structures and Design","topic":"Fuel Storage Structure","question":"A common aircraft wing design that seals the internal structural skin and spars to store fuel directly without rubber bladders is a:","options":["A. Dry wing design","B. Fuel wing design","C. Wet wing design (integral fuel tank)","D. Central tank design"],"correct_answer":"C","explanation":"Wet wing construction utilizes the sealed internal structural volume between front and rear spars for fuel containment."},
  {"id":"STRUC-052","subject":"Aircraft Structures and Design","topic":"Fail-Safe Design","question":"Structural designs incorporating redundant load paths and damage containment so that failure of a single member does not lead to catastrophic loss are:","options":["A. Fail-safe designs","B. Safe-life designs","C. Infinite-life designs","D. Monocoque designs"],"correct_answer":"A","explanation":"Fail-safe design guarantees flight safety by providing backup load paths in the event of local structural failure."},
  {"id":"STRUC-053","subject":"Aircraft Structures and Design","topic":"Flight Controls Classification","question":"Which of the following is NOT a primary flight control surface?","options":["A. Aileron","B. Elevator","C. Flaps","D. Rudder"],"correct_answer":"C","explanation":"Primary controls are Ailerons, Elevators, and Rudder. Flaps are secondary/high-lift devices."},
  {"id":"STRUC-054","subject":"Aircraft Structures and Design","topic":"Aircraft Zoning","question":"In standard aircraft maintenance zoning (ATA 100), Zone 400 designates the:","options":["A. Left wing","B. Right wing","C. Powerplants and Nacelles","D. Empennage"],"correct_answer":"C","explanation":"Zone 100 = Lower Fuselage, Zone 200 = Upper Fuselage, Zone 300 = Empennage, Zone 400 = Nacelles/Powerplants, Zone 500 = Left Wing, Zone 600 = Right Wing."},
  {"id":"STRUC-055","subject":"Aircraft Structures and Design","topic":"Equilibrium Flight","question":"Which statement is strictly true during straight, level, unaccelerated flight?","options":["A. Lift = Drag","B. Lift = Thrust","C. Lift = Weight and Thrust = Drag","D. Lift exceeds Weight by 50%"],"correct_answer":"C","explanation":"In steady unaccelerated level flight, vertical forces balance (L = W) and horizontal forces balance (T = D)."},
  {"id":"STRUC-056","subject":"Aircraft Structures and Design","topic":"Aircraft Stability","question":"The inherent property of an aircraft that causes it to return to its original trimmed equilibrium flight path without pilot control input is:","options":["A. Stability","B. Maneuverability","C. Controllability","D. Operability"],"correct_answer":"A","explanation":"Positive static and dynamic stability restore the aircraft to trimmed equilibrium following disturbances."},
  {"id":"STRUC-057","subject":"Aircraft Structures and Design","topic":"Beam Reactions","question":"A 500 kg concentrated load acts at the midpoint of a 300 ft simply supported beam. What are the reactions at both supports?","options":["A. 250 kg, 250 kg","B. 300 kg, 200 kg","C. 100 kg, 400 kg","D. 500 kg, 0 kg"],"correct_answer":"A","explanation":"By symmetry, each end reaction carries half the centered load: R1 = R2 = 500 / 2 = 250 kg."},
  {"id":"STRUC-058","subject":"Aircraft Structures and Design","topic":"Inelastic Deformation","question":"A permanent deformation where the material remains distorted and does not return to its original dimensions upon load release is:","options":["A. Plastic deformation","B. Elastic deformation","C. Creep deformation","D. Resilience"],"correct_answer":"A","explanation":"Deformation beyond the elastic limit into the plastic regime produces permanent set."},
  {"id":"STRUC-059","subject":"Aircraft Structures and Design","topic":"Hooke's Law","question":"In the linear stress-strain diagram, the constant slope of proportionality (E) represents:","options":["A. Modulus of Rigidity","B. Bulk Modulus","C. Young's Modulus of Elasticity","D. Poisson's Ratio"],"correct_answer":"C","explanation":"Young's Modulus E = sigma / epsilon (stress divided by strain in the elastic region)."},
  {"id":"STRUC-060","subject":"Aircraft Structures and Design","topic":"FAR Regulations","question":"Which of the following aircraft categories is NOT covered under FAR Part 23?","options":["A. Normal category","B. Utility category","C. Commuter category","D. Transport category"],"correct_answer":"D","explanation":"Transport category aircraft are governed strictly by FAR Part 25 (FAR Part 23 covers Normal, Utility, Acrobatic, and Commuter)."},
  {"id":"STRUC-061","subject":"Aircraft Structures and Design","topic":"Moment Definition","question":"The rotational turning effect produced on an axis by a force applied at a perpendicular distance from that axis is:","options":["A. Inertia","B. Equilibrium","C. Moment (Torque)","D. Momentum"],"correct_answer":"C","explanation":"Moment M = Force × Perpendicular Distance (Torque)."},
  {"id":"STRUC-062","subject":"Aircraft Structures and Design","topic":"Landing Gear Types","question":"Which of the following is NOT an advantage of a conventional (tailwheel) landing gear arrangement?","options":["A. Good forward pilot field of view during taxi","B. Lighter airframe structural weight","C. Better propeller ground clearance","D. Automatic positive angle of attack for takeoff"],"correct_answer":"A","explanation":"Tailwheel aircraft have poor forward over-the-nose visibility while taxiing on the ground."},
  {"id":"STRUC-063","subject":"Aircraft Structures and Design","topic":"Control Tabs","question":"A control tab that is mechanically geared to move in the opposite direction of the primary control surface to reduce required stick force is a:","options":["A. Servo tab (Balance tab)","B. Anti-servo tab","C. Trim tab","D. Spring tab"],"correct_answer":"A","explanation":"Servo and balance tabs deflect oppositely to assist the pilot in deflecting heavy control surfaces."},
  {"id":"STRUC-064","subject":"Aircraft Structures and Design","topic":"Statics Theorems","question":"Varignon's Theorem states that:","options":["A. Stress is proportional to strain","B. Fluid pressure is transmitted equally","C. The moment of a force about any point equals the algebraic sum of the moments of its components about that same point","D. Energy is conserved in an elastic system"],"correct_answer":"C","explanation":"Varignon's Principle of Moments: M_O(R) = Sigma M_O(F_i)."},
  {"id":"STRUC-065","subject":"Aircraft Structures and Design","topic":"Helicopter CG","question":"In helicopter structural design, the center of gravity is ideally located:","options":["A. Aft of the main rotor hub","B. Directly on the vertical centerline axis of the main rotor hub","C. Forward of the cockpit","D. Near the tail rotor gearbox"],"correct_answer":"B","explanation":"Aligning the CG directly under the main rotor shaft ensures neutral trim in hover without excessive cyclic displacement."},
  {"id":"STRUC-066","subject":"Aircraft Structures and Design","topic":"Nonlinear Lift Distribution","question":"A 16-ft wing is subjected to lift distribution w = 90*sqrt(x) lb/ft from tip (x=0) to root (x=16). Find the total lift and its centroidal distance from the tip.","options":["A. 3,840 lbs & 5.6 ft","B. 3,840 lbs & 9.6 ft","C. 3,040 lbs & 5.6 ft","D. 3,040 lbs & 9.6 ft"],"correct_answer":"B","explanation":"Total Lift = integral from 0 to 16 of 90*x^0.5 dx = [60*x^1.5] = 60*(64) = 3,840 lbs. x_bar = integral(90*x^1.5 dx) / 3840 = (36*16^2.5) / 3840 = 36864 / 3840 = 9.6 ft from tip."},
  {"id":"STRUC-067","subject":"Aircraft Structures and Design","topic":"Truss Determinacy","question":"A planar truss structure with 3 support reaction unknowns and joint equations satisfying m + 3 = 2j is:","options":["A. Unstable","B. Statically determinate","C. Statically indeterminate","D. Redundant"],"correct_answer":"B","explanation":"When the number of independent equilibrium equations equals the number of unknown member forces and reactions, it is statically determinate."},
  {"id":"STRUC-068","subject":"Aircraft Structures and Design","topic":"Stress Definition","question":"The measure of internal force intensity acting per unit area across an internal section of a body is:","options":["A. Strain","B. Stress","C. Force","D. Pressure"],"correct_answer":"B","explanation":"Stress is the internal load intensity resisting externally applied forces."},
  {"id":"STRUC-069","subject":"Aircraft Structures and Design","topic":"Punching Shear","question":"What force is required to punch a 20 mm diameter hole through an aluminum plate 25 mm thick if the ultimate shear strength is 350 MPa?","options":["A. 345 kN","B. 550 kN","C. 221 kN","D. 566 kN"],"correct_answer":"B","explanation":"Shear area A = pi * d * t = pi * (0.020) * (0.025) = 0.0015708 m². Force F = 350 x 10⁶ * 0.0015708 = 549,778 N ≈ 550 kN."},
  {"id":"STRUC-070","subject":"Aircraft Structures and Design","topic":"Poisson's Ratio","question":"Poisson's ratio is defined as the absolute ratio of:","options":["A. Stress to strain","B. Young's modulus to shear modulus","C. Lateral strain to longitudinal (axial) strain","D. Plastic strain to elastic strain"],"correct_answer":"C","explanation":"nu = |epsilon_lateral / epsilon_longitudinal|."},
  {"id":"STRUC-071","subject":"Aircraft Structures and Design","topic":"Canard Configurations","question":"An aircraft design featuring a forward horizontal surface ahead of the main wing that carries positive lift while providing pitch control is a:","options":["A. Control canard","B. Sweptback wing","C. Lifting canard","D. Tandem wing"],"correct_answer":"C","explanation":"A lifting canard contributes positively to total aircraft lift while controlling pitch."},
  {"id":"STRUC-072","subject":"Aircraft Structures and Design","topic":"Monocoque Construction","question":"A structural design that relies primarily on the outer stressed skin to carry all primary flight bending and torsion loads is:","options":["A. Monocoque","B. Semi-monocoque","C. Truss","D. Geodetic"],"correct_answer":"A","explanation":"Monocoque construction carries all loads in the external shell."},
  {"id":"STRUC-073","subject":"Aircraft Structures and Design","topic":"Wing Dihedral","question":"The upward angle of aircraft wings relative to the horizontal plane is dihedral, whose primary function is to provide:","options":["A. Longitudinal stability","B. Lateral (roll) stability","C. Directional stability","D. High maximum lift"],"correct_answer":"B","explanation":"Dihedral generates a restoring rolling moment whenever the aircraft enters a sideslip."},
  {"id":"STRUC-074","subject":"Aircraft Structures and Design","topic":"V-Speeds","question":"During the takeoff roll of a multi-engine transport aircraft, V1 represents the:","options":["A. Minimum unstick speed","B. Rotation speed","C. Takeoff decision speed (critical engine failure recognition speed)","D. Best angle of climb speed"],"correct_answer":"C","explanation":"V1 is the decision speed above which takeoff must continue even if an engine fails."},
  {"id":"STRUC-075","subject":"Aircraft Structures and Design","topic":"Biplane Geometry","question":"In biplane wing design, stagger is defined as the:","options":["A. Longitudinal offset of the two wings relative to each other along the fuselage axis","B. Difference in wing incidence angles","C. Vertical spacing between wings","D. Difference in wing spans"],"correct_answer":"A","explanation":"Stagger is the fore-and-aft relative displacement between upper and lower wings."},
  {"id":"STRUC-076","subject":"Aircraft Structures and Design","topic":"Elastic Limit","question":"The maximum stress to which a material can be subjected without incurring any permanent plastic deformation is the:","options":["A. Elastic limit","B. Ultimate strength","C. Rupture strength","D. Proportional limit"],"correct_answer":"A","explanation":"Beyond the elastic limit, permanent plastic strain remains upon unloading."},
  {"id":"STRUC-077","subject":"Aircraft Structures and Design","topic":"Resilience","question":"The capacity of a structural material to absorb mechanical energy elastically without permanent distortion is:","options":["A. Toughness","B. Hardness","C. Resilience (Modulus of Resilience)","D. Ductility"],"correct_answer":"C","explanation":"Resilience represents elastic energy storage capacity (area under elastic stress-strain curve)."},
  {"id":"STRUC-078","subject":"Aircraft Structures and Design","topic":"Working Stress","question":"The actual calculated stress occurring in a structural component under normal operating service loads is the:","options":["A. Allowable stress","B. Working stress (Operating stress)","C. Ultimate stress","D. Proof stress"],"correct_answer":"B","explanation":"Working stress is the actual stress experienced in service, designed to stay safely below allowable limits."},
  {"id":"STRUC-079","subject":"Aircraft Structures and Design","topic":"Axial Bar Deflection","question":"An aluminum bar (A = 0.5 sq in, E = 10 x 10⁶ psi) carries axial loads. What is the net elongation?","options":["A. 0.0798 in lengthening","B. 0.0798 in shortening","C. 0.0696 in lengthening","D. 0.0696 in shortening"],"correct_answer":"C","explanation":"delta = Sigma(P*L / (A*E)) across all segments = 0.0696 inches lengthening."},
  {"id":"STRUC-080","subject":"Aircraft Structures and Design","topic":"Elastic Constants Relationship","question":"For an isotropic elastic material, the relation connecting Young's Modulus (E), Shear Modulus (G), and Poisson's ratio (nu) is:","options":["A. G = E / 2","B. G = 2E(1 + nu)","C. G = E / [2(1 + nu)] (directly proportional)","D. G is independent of E"],"correct_answer":"C","explanation":"G = E / [2(1 + nu)]. Since nu is constant, G is directly proportional to E."},
  {"id":"STRUC-081","subject":"Aircraft Structures and Design","topic":"Torsional Shear Stress","question":"A solid steel shaft (L = 5 m, G = 83 GPa) twists through 4° (0.06981 rad) at a maximum surface shear stress of 80 MPa. What is its diameter?","options":["A. 135 mm","B. 138 mm","C. 140 mm","D. 132 mm"],"correct_answer":"B","explanation":"tau = G * r * theta / L => d = 2*tau*L / (G*theta) = 2(80e6)(5) / (83e9 * 0.06981) = 800 / 5,794.2 = 0.1380 m = 138 mm."},
  {"id":"STRUC-082","subject":"Aircraft Structures and Design","topic":"Thin-Walled Tube Torsion","question":"A thin-walled hollow tube with wall thickness t = 2 mm and mean enclosed area A_m carries a torque of 600 N-m. What is the shear stress?","options":["A. 79.40 MPa","B. 78.99 MPa","C. 80.54 MPa","D. 78.36 MPa"],"correct_answer":"D","explanation":"By Bredt's formula: tau = T / (2 * A_m * t) = 600 / (2 * 0.003828 * 0.002) = 78.36 MPa."},
  {"id":"STRUC-083","subject":"Aircraft Structures and Design","topic":"Beam Maximum Moment","question":"For a simply supported beam with concentrated loads of 30 kN and 50 kN, what is the maximum bending moment?","options":["A. 58 kN-m","B. 56 kN-m","C. 54 kN-m","D. 52 kN-m"],"correct_answer":"C","explanation":"Constructing the shear and moment diagram yields a maximum bending moment of 54 kN-m."},
  {"id":"STRUC-084","subject":"Aircraft Structures and Design","topic":"Point of Maximum Moment","question":"On a beam carrying transverse loadings, the maximum bending moment occurs at the exact section where:","options":["A. Shear force is maximum","B. Shear force is zero (or passes through zero)","C. Deflection is zero","D. Reactions are applied"],"correct_answer":"B","explanation":"dM/dx = V(x). The bending moment reaches a mathematical extremum where shear V = 0."},
  {"id":"STRUC-085","subject":"Aircraft Structures and Design","topic":"Mass Definition","question":"The intrinsic physical property measuring the quantity of matter in a body and its resistance to acceleration is:","options":["A. Weight","B. Volume","C. Density","D. Mass"],"correct_answer":"D","explanation":"Mass is the scalar measure of inertia and matter quantity."},
  {"id":"STRUC-086","subject":"Aircraft Structures and Design","topic":"Newton's Third Law","question":"Newton's Third Law of Motion states that:","options":["A. F = m * a","B. Energy cannot be destroyed","C. For every applied action force, there is an equal, opposite, and collinear reaction force","D. Momentum is always conserved"],"correct_answer":"C","explanation":"Action and reaction forces between interacting bodies are equal in magnitude and opposite in direction."},
  {"id":"STRUC-087","subject":"Aircraft Structures and Design","topic":"Force Equilibrium Angle","question":"Three coplanar forces of 20 N, 30 N, and 40 N are in static equilibrium. Find the largest angle between any two forces.","options":["A. 105.5°","B. 104.5°","C. 103.5°","D. 102.5°"],"correct_answer":"B","explanation":"The largest angle theta faces the largest resultant side (40 N): cos(180° - theta) = (20² + 30² - 40²) / (2*20*30) = -300/1200 = -0.25 => theta = 104.48° ≈ 104.5°."},
  {"id":"STRUC-088","subject":"Aircraft Structures and Design","topic":"Truss Determinacy Criteria","question":"A planar truss has 15 joints, 27 members, and 3 reaction components. The structure is:","options":["A. Statically determinate and stable (m + r = 2j = 30)","B. Statically indeterminate","C. Unstable and determinate","D. Redundant"],"correct_answer":"A","explanation":"m + r = 27 + 3 = 30; 2*j = 2*15 = 30. Since m + r = 2j and properly braced, it is statically determinate and stable."},
  {"id":"STRUC-089","subject":"Aircraft Structures and Design","topic":"Truss Member Force","question":"In a 45° planar truss carrying a vertical load of 20 kN at its tip, the internal force in diagonal member AB is:","options":["A. 20 kN (T)","B. 28.28 kN (T)","C. 20 kN (C)","D. 28.28 kN (C)"],"correct_answer":"D","explanation":"F_AB = 20 / sin(45°) = 20 * 1.4142 = 28.28 kN in compression (C)."},
  {"id":"STRUC-090","subject":"Aircraft Structures and Design","topic":"Pratt Truss Member Force","question":"In a Pratt bridge truss carrying 3,000 lb, member HC is found by method of sections to carry:","options":["A. 5,625 lb (Tension)","B. 625 lb (Tension)","C. 5,625 lb (Compression)","D. 625 lb (Compression)"],"correct_answer":"A","explanation":"Taking moments about joint E yields F_HC = 5,625 lbs in tension."},
  {"id":"STRUC-091","subject":"Aircraft Structures and Design","topic":"Limit Load","question":"The maximum anticipated flight load factor that an aircraft is expected to encounter during its operational life is the:","options":["A. Limit load","B. Ultimate load","C. Gust factor","D. Dynamic load"],"correct_answer":"A","explanation":"Limit load is the maximum service design load (n_limit)."},
  {"id":"STRUC-092","subject":"Aircraft Structures and Design","topic":"Rigid Body Translation","question":"If the unbalanced forces acting on a rigid body change only the velocity magnitude without changing its orientation or direction, the motion is:","options":["A. Rotation","B. Rectilinear Translation","C. Curvilinear translation","D. Transformation"],"correct_answer":"B","explanation":"Pure rectilinear translation moves all particles along parallel straight lines."},
  {"id":"STRUC-093","subject":"Aircraft Structures and Design","topic":"Aerodynamic Center","question":"The point along an airfoil chord about which the aerodynamic pitching moment remains constant with changes in angle of attack is the:","options":["A. Center of Pressure","B. Center of Gravity","C. Aerodynamic Center (AC)","D. Elastic Axis"],"correct_answer":"C","explanation":"For thin sub-critical airfoils, the aerodynamic center is located at the quarter-chord point (25% chord)."},
  {"id":"STRUC-094","subject":"Aircraft Structures and Design","topic":"Tire Hydroplaning","question":"When an aircraft tire hydroplanes on a flooded runway, dynamic water pressure separates the tire from the runway, causing the friction coefficient to drop to:","options":["A. 1.0","B. 0.5","C. 0.0 (near zero friction)","D. 0.8"],"correct_answer":"C","explanation":"Dynamic hydroplaning creates a water film that reduces braking and steering friction to near zero."},
  {"id":"STRUC-095","subject":"Aircraft Structures and Design","topic":"Airframe Repairability","question":"Built-up sheet metal aircraft structural units (spars, ribs, and longerons) that sustain localized damage are normally:","options":["A. Repairable using approved maintenance manual procedures and splice doublers","B. Not repairable and must be scrapped","C. Repairable only by welding","D. Covered with tape"],"correct_answer":"A","explanation":"Standard structural repair manuals (SRM) provide approved riveted doubler and splice repair schemes."},
  {"id":"STRUC-096","subject":"Aircraft Structures and Design","topic":"Fluid Line Identification","question":"In aircraft plumbing color coding, fire-extinguisher lines are identified by bands of:","options":["A. Yellow","B. Red and Green","C. Blue and Black","D. Brown"],"correct_answer":"D","explanation":"Under MIL-STD-1247, brown markings designate fire protection / extinguisher plumbing."},
  {"id":"STRUC-097","subject":"Aircraft Structures and Design","topic":"Fuel Tanks","question":"Integral fuel tanks differ from bladder tanks in that they are:","options":["A. Nonmetallic removable cells","B. Formed directly by the sealed airframe structure itself","C. External drop tanks","D. Made of canvas"],"correct_answer":"B","explanation":"Integral tanks use the sealed airframe skin and spars as the fuel container."},
  {"id":"STRUC-098","subject":"Aircraft Structures and Design","topic":"Dynamics Branches","question":"The branch of classical mechanics that studies the geometry of pure motion of bodies without considering the forces causing the motion is:","options":["A. Kinetics","B. Kinematics","C. Statics","D. Mechatronics"],"correct_answer":"B","explanation":"Kinematics describes displacement, velocity, and acceleration independent of mass and forces."},
  {"id":"STRUC-099","subject":"Aircraft Structures and Design","topic":"Clevis Joint Bolt Sizing","question":"In a double-shear clevis joint carrying 14,000 lbs (14 kips) with allowable shear stress tau = 12 ksi, what is the minimum required bolt diameter?","options":["A. 0.8681 in","B. 0.8618 in","C. 0.4061 in","D. 0.4016 in"],"correct_answer":"B","explanation":"Double shear area = 2 * (pi/4)*d² = 14 / 12 = 1.1667 sq in => d² = 1.1667 / 1.5708 = 0.7427 => d = 0.8618 inches."},
  {"id":"STRUC-100","subject":"Aircraft Structures and Design","topic":"Clevis Yoke Thickness","question":"For the 14-kip clevis joint (bolt d = 0.8618 in), if allowable bearing stress is 20 ksi, find the minimum thickness (t) of each of the two yoke prongs.","options":["A. 0.8618 in","B. 0.5000 in","C. 0.4061 in","D. 0.3500 in"],"correct_answer":"C","explanation":"Bearing load on each prong = 14 / 2 = 7 kips. sigma_b = P / (d * t) => 20 = 7 / (0.8618 * t) => t = 7 / (20 * 0.8618) = 0.4061 inches."},

  // SECTION 3: CALCULATIONS & PRC LICENSURE ITEMS (ITEMS 101-185+)
  {"id":"STRUC-101","subject":"Aircraft Structures and Design","topic":"Tension Tube Sizing","question":"Determine the outside diameter (D) of a hollow steel tube carrying 500 kN tensile load at 140 MPa, where wall thickness t = 0.1D.","options":["A. 111.3 mm","B. 109.7 mm","C. 113.7 mm","D. 112.4 mm"],"correct_answer":"C","explanation":"Area A = pi/4 * [D² - (0.8D)²] = (pi/4)*(0.36 D²) = 0.2827 D². A = 500,000 / 140e6 = 0.003571 m² => D² = 0.003571 / 0.2827 = 0.01263 m² => D = 0.1124 m ≈ 113.7 mm."},
  {"id":"STRUC-102","subject":"Aircraft Structures and Design","topic":"Thermal Expansion","question":"A 200-ft iron steam pipe at 0°C is heated to 100°C. With coefficient of thermal expansion alpha = 10 x 10^-6 /°C, what is its elongation?","options":["A. 0.18 ft","B. 0.12 ft","C. 0.28 ft","D. 0.20 ft"],"correct_answer":"D","explanation":"delta_L = L * alpha * delta_T = 200 * (10 x 10^-6) * 100 = 0.20 ft."},
  {"id":"STRUC-103","subject":"Aircraft Structures and Design","topic":"Beam Shear & Moment","question":"For a simply supported beam carrying a uniformly distributed load over its entire span:","options":["A. Maximum bending moment occurs at supports","B. Maximum shear occurs at midspan","C. Maximum shear occurs at the end supports, and maximum bending moment at midspan","D. Shear is uniform throughout"],"correct_answer":"C","explanation":"Shear is maximum at reactions (wL/2) and zero at center; moment is maximum at center (wL²/8)."},
  {"id":"STRUC-104","subject":"Aircraft Structures and Design","topic":"Moment Calculation","question":"A simply supported 10-meter beam carries a uniform load of 20 kN/m. What is the maximum bending moment?","options":["A. 10,000 kN-m","B. 5,000 kN-m","C. 2,000 kN-m","D. 250 kN-m"],"correct_answer":"D","explanation":"M_max = w * L² / 8 = 20 * (10)² / 8 = 2000 / 8 = 250 kN-m."},
  {"id":"STRUC-105","subject":"Aircraft Structures and Design","topic":"Bar Elongation","question":"A 30-meter aluminum bar is subjected to tensile stress of 172 MPa (E = 69,116 MPa). Find its total elongation.","options":["A. 0.0746 m (7.46 cm)","B. 0.0075 m","C. 6.27 mm","D. 74.6 cm"],"correct_answer":"A","explanation":"delta = sigma * L / E = (172 / 69116) * 30 m = 0.0024886 * 30 = 0.0746 m = 7.46 cm."},
  {"id":"STRUC-106","subject":"Aircraft Structures and Design","topic":"Landing Rollout Distance","question":"A 20,000-lb airplane touches down at 100 mph (146.67 ft/s) with a constant braking force of 8,000 lb. Find its landing run distance.","options":["A. 845 ft","B. 800 ft","C. 835 ft","D. 735 ft"],"correct_answer":"C","explanation":"Deceleration a = F/m = 8000 / (20000/32.2) = 12.88 ft/s². Distance S = V² / (2a) = 146.67² / (2 * 12.88) = 21511 / 25.76 = 835.0 ft."},
  {"id":"STRUC-107","subject":"Aircraft Structures and Design","topic":"Carrier Arresting Gear","question":"A 10,000-lb airplane landing on an aircraft carrier engages the arresting cable and decelerates at 3g (96.6 ft/s²). What is the tension in the cable?","options":["A. 30,500 lb","B. 35,000 lb","C. 30,000 lb","D. 50,000 lb"],"correct_answer":"A","explanation":"Tension T = (m * a) / cos(theta) = (10,000 * 3) / cos(10°) = 30,000 / 0.9848 = 30,463 ≈ 30,500 lbs."},
  {"id":"STRUC-108","subject":"Aircraft Structures and Design","topic":"Carrier Cable Moment Arm","question":"During carrier arrestment, the moment arm distance (e) from the airplane CG to the arresting cable line of action is:","options":["A. 10 in","B. 20 in","C. 15 in","D. 25 in"],"correct_answer":"A","explanation":"Moment equilibrium about the main landing gear resolves e = 10 inches."},
  {"id":"STRUC-109","subject":"Aircraft Structures and Design","topic":"Carrier Arresting Distance","question":"For the carrier landing at initial touchdown speed 80 ft/s decelerating at 3g (96.6 ft/s²), find the arresting stopping run.","options":["A. 33 ft","B. 22 ft","C. 11 ft","D. 44 ft"],"correct_answer":"A","explanation":"S = V² / (2a) = 80² / (2 * 96.6) = 6400 / 193.2 = 33.12 ≈ 33 ft."},
  {"id":"STRUC-110","subject":"Aircraft Structures and Design","topic":"Bomb Trajectory Range","question":"An aircraft flying horizontally at 300 km/h (83.33 m/s) at 1,000 m drops a bomb to hit a target at 200 m elevation. Find the release distance.","options":["A. 1,024.2 m","B. 1,055.6 m","C. 1,075.5 m","D. 1,064.2 m"],"correct_answer":"D","explanation":"Fall height h = 1000 - 200 = 800 m. Time t = sqrt(2h / g) = sqrt(1600 / 9.81) = 12.77 s. Range = V * t = 83.33 * 12.77 = 1,064.2 m."},
  {"id":"STRUC-111","subject":"Aircraft Structures and Design","topic":"Kinematic Acceleration","question":"A particle moves with position x(t) = 3.4 t³ - 5.4 t. Find its acceleration at t = 5 seconds.","options":["A. 51.0 m/s²","B. 102.0 m/s²","C. 3.4 m/s²","D. 18.1 m/s²"],"correct_answer":"B","explanation":"v(t) = x'(t) = 10.2 t² - 5.4; a(t) = v'(t) = 20.4 t. At t = 5: a = 20.4(5) = 102 m/s²."},
  {"id":"STRUC-112","subject":"Aircraft Structures and Design","topic":"Projectile Range","question":"A projectile is launched at 100 m/s at 30° elevation. How far horizontally will it travel before returning to launch level?","options":["A. 890 m","B. 883 m","C. 880 m","D. 875 m"],"correct_answer":"B","explanation":"R = (v² * sin(2*theta)) / g = (100² * sin(60°)) / 9.81 = (10,000 * 0.8660) / 9.81 = 882.8 ≈ 883 m."},
  {"id":"STRUC-113","subject":"Aircraft Structures and Design","topic":"Projectile Apogee","question":"A projectile leaves with velocity 50 m/s at 30° above horizontal. Find its maximum height (apogee).","options":["A. 31.86 m","B. 31.28 m","C. 30.63 m","D. 30.12 m"],"correct_answer":"A","explanation":"v_y0 = 50 * sin(30°) = 25 m/s. h_max = v_y0² / (2g) = 25² / (2 * 9.81) = 625 / 19.62 = 31.86 m."},
  {"id":"STRUC-114","subject":"Aircraft Structures and Design","topic":"Flywheel Deceleration","question":"A flywheel rotating at 60 rpm (1 rev/s) is stopped in 8 seconds under uniform deceleration. How many revolutions does it make?","options":["A. 8 turns","B. 3 turns","C. 4 turns","D. 6 turns"],"correct_answer":"C","explanation":"Total revolutions = (omega_0 + omega_f)/2 * t = (1.0 + 0)/2 * 8 = 4 revolutions (turns)."},
  {"id":"STRUC-115","subject":"Aircraft Structures and Design","topic":"Angular Velocity","question":"A rotating wheel of radius r = 2.5 ft moves a point on its rim 30 ft in 2 seconds (v = 15 ft/s). Find its angular velocity.","options":["A. 2 rad/s","B. 4 rad/s","C. 5 rad/s","D. 6 rad/s"],"correct_answer":"D","explanation":"omega = v / r = (30 ft / 2 s) / 2.5 ft = 15 / 2.5 = 6 rad/s."},
  {"id":"STRUC-116","subject":"Aircraft Structures and Design","topic":"Centripetal Acceleration","question":"A vehicle on an 800-ft radius track travels at 27 ft/s with tangential acceleration a_t = 3 ft/s². Find total resultant acceleration.","options":["A. 2.8 ft/s²","B. 3.0 ft/s²","C. 3.14 ft/s²","D. 4.2 ft/s²"],"correct_answer":"C","explanation":"a_n = v² / R = 27² / 800 = 729 / 800 = 0.911 ft/s². a_total = sqrt(a_t² + a_n²) = sqrt(3² + 0.911²) = sqrt(9.83) = 3.135 ≈ 3.14 ft/s²."},
  {"id":"STRUC-117","subject":"Aircraft Structures and Design","topic":"Newtonian Acceleration","question":"What force accelerates a 30,000-lb car at 1.25 ft/s² against a constant frictional resistance of 400 lbs?","options":["A. 1,565 lbs","B. 1,585 lbs","C. 1,595 lbs","D. 1,575 lbs"],"correct_answer":"A","explanation":"F_net = m * a = (30,000 / 32.2) * 1.25 = 1,164.6 lbs. Total Force F = 1164.6 + 400 = 1,564.6 ≈ 1,565 lbs."},
  {"id":"STRUC-118","subject":"Aircraft Structures and Design","topic":"Equilibrium Triangle","question":"Three forces 20 N, 30 N, and 40 N are in static equilibrium. Find the largest angle between any two vectors.","options":["A. 105.5°","B. 104.5°","C. 106.7°","D. 107.9°"],"correct_answer":"B","explanation":"cos(180° - theta) = (20² + 30² - 40²) / (2*20*30) = -300 / 1200 = -0.25 => theta = 104.5°."},
  {"id":"STRUC-119","subject":"Aircraft Structures and Design","topic":"Friction Incline","question":"A 40-kg block rests on a 20° incline with coefficient of friction mu = 0.6. What force parallel to the incline causes impending downward motion?","options":["A. 82 N","B. 77 N","C. 87 N","D. 72 N"],"correct_answer":"C","explanation":"P = W * (mu * cos 20° - sin 20°) = 40(9.81) * (0.6 * 0.9397 - 0.3420) = 392.4 * (0.5638 - 0.3420) = 392.4 * 0.2218 = 87.0 N."},
  {"id":"STRUC-120","subject":"Aircraft Structures and Design","topic":"Moment of Inertia Rectangle","question":"A rectangle has base b = 3 cm and height h = 6 cm. Find its moment of inertia (second moment of area) about its centroidal axis parallel to base.","options":["A. 64 cm⁴","B. 36 cm⁴","C. 44 cm⁴","D. 54 cm⁴"],"correct_answer":"D","explanation":"I_x = b * h³ / 12 = 3 * (6)³ / 12 = 3 * 216 / 12 = 54 cm⁴."},
  {"id":"STRUC-121","subject":"Aircraft Structures and Design","topic":"Polar Moment of Inertia Circle","question":"Find the polar moment of inertia (J) of a 20-cm diameter circle about its centroidal polar axis.","options":["A. 14,280 cm⁴","B. 15,708 cm⁴","C. 17,279 cm⁴","D. 19,007 cm⁴"],"correct_answer":"B","explanation":"J = pi * D⁴ / 32 = pi * (20)⁴ / 32 = pi * 160,000 / 32 = 5,000 * pi = 15,707.96 ≈ 15,708 cm⁴."},
  {"id":"STRUC-122","subject":"Aircraft Structures and Design","topic":"Triangle Moment of Inertia","question":"An isosceles triangle has base b = 10 cm and altitude h = 10 cm. Find the moment of inertia about a line parallel to base through its apex vertex.","options":["A. 2,750 cm⁴","B. 3,025 cm⁴","C. 2,500 cm⁴","D. 2,273 cm⁴"],"correct_answer":"C","explanation":"I_vertex = b * h³ / 4 = 10 * (10)³ / 4 = 10,000 / 4 = 2,500 cm⁴."},
  {"id":"STRUC-123","subject":"Aircraft Structures and Design","topic":"Wing Aspect Ratio Factors","question":"What physical factors are involved in determining the aspect ratio of aircraft wings?","options":["A. Thickness and chord","B. Wingspan and chord","C. Dihedral and angle of attack","D. Area and thickness"],"correct_answer":"B","explanation":"Aspect ratio = Span / Mean Chord (b/c) or b² / S."},
  {"id":"STRUC-124","subject":"Aircraft Structures and Design","topic":"Cantilever Wing","question":"A cantilever wing structure is characterized by:","options":["A. Nonadjustable external struts","B. Complete internal support with no external bracing or struts","C. Single external lift struts","D. Fabric-wrapped truss"],"correct_answer":"B","explanation":"Cantilever wings rely on internal structural spars without external struts."},
  {"id":"STRUC-125","subject":"Aircraft Structures and Design","topic":"Fuselage Bending Resistance","question":"In a semi-monocoque fuselage, which structural elements primarily resist axial tension and compression caused by bending?","options":["A. Fuselage covering only","B. Longerons and stringers","C. Bulkheads and skin","D. Formers only"],"correct_answer":"B","explanation":"Longitudinal longerons and stringers carry axial tension and compression from overall fuselage bending."},
  {"id":"STRUC-126","subject":"Aircraft Structures and Design","topic":"Fuselage Frame Types","question":"Fuselage transverse frames that serve as anchor points for medium-weight equipment and flight control systems are:","options":["A. Simple frames","B. Main frames","C. Intermediate frames","D. Subframes"],"correct_answer":"C","explanation":"Intermediate frames distribute local concentrated equipment loads into the shell."},
  {"id":"STRUC-127","subject":"Aircraft Structures and Design","topic":"Aircraft Useful Load","question":"For general transport aircraft, useful load (payload plus usable fuel) typically ranges from what percentage of gross weight?","options":["A. 10% to 20%","B. 25% to 40%","C. 5% to 10%","D. 30% to 50%"],"correct_answer":"D","explanation":"Useful load fraction typically spans 30% to 50% of maximum takeoff weight."},
  {"id":"STRUC-128","subject":"Aircraft Structures and Design","topic":"Friction Angle","question":"The angle phi whose tangent equals the ratio of frictional force to normal reaction force (tan phi = F_f / N = mu) is the:","options":["A. Weight angle","B. Angle of Friction","C. Angle of Repose","D. Coefficient angle"],"correct_answer":"B","explanation":"The angle of friction phi satisfies tan(phi) = mu."},
  {"id":"STRUC-129","subject":"Aircraft Structures and Design","topic":"Airframe Backbone","question":"The central body of an aircraft to which the wings, landing gear, and tail empennage surfaces are attached is the:","options":["A. Fuselage","B. Empennage","C. Nacelle","D. Cabin"],"correct_answer":"A","explanation":"The fuselage is the primary body providing payload space and structural connectivity."},
  {"id":"STRUC-130","subject":"Aircraft Structures and Design","topic":"Design Disciplines","question":"The phase of aircraft design concerned with predicting flight speeds, climb rates, range, and operational envelopes belongs to:","options":["A. Thermodynamics","B. Metallurgy","C. Structural dynamics","D. Aerodynamics"],"correct_answer":"D","explanation":"Aerodynamic performance analysis determines vehicle lift, drag, and flight capabilities."},
  {"id":"STRUC-131","subject":"Aircraft Structures and Design","topic":"Rate of Climb Horsepower","question":"An airplane has 1,200 hp available and 700 hp required. If gross weight is 10,000 lbs, what is its rate of climb?","options":["A. 1,600 fpm","B. 1,700 fpm","C. 1,750 fpm","D. 1,650 fpm"],"correct_answer":"D","explanation":"Excess HP = 1200 - 700 = 500 hp. RC = (500 * 33,000 ft-lb/min) / 10,000 lb = 16,500,000 / 10,000 = 1,650 ft/min."},
  {"id":"STRUC-132","subject":"Aircraft Structures and Design","topic":"Applied Load Process","question":"Converting basic aerodynamic flight conditions into representative distributed external airloads for stress analysis is:","options":["A. Applied load process (Balancing the airplane)","B. Simulation process","C. Failure process","D. Proof testing"],"correct_answer":"A","explanation":"Balancing the airplane ensures net aerodynamic, inertial, and propulsive loads satisfy D'Alembert equilibrium."},
  {"id":"STRUC-133","subject":"Aircraft Structures and Design","topic":"Lateral Stability Design","question":"Lateral (roll) stability in aircraft is primarily achieved through:","options":["A. High angle of incidence","B. Providing a positive dihedral angle on the wings","C. Forward CG location","D. Rudder trim"],"correct_answer":"B","explanation":"Wing dihedral produces a restoring roll moment during any sideslip excursion."},
  {"id":"STRUC-134","subject":"Aircraft Structures and Design","topic":"Power Available Source","question":"The Power Available (Pa) curve is an aerodynamic-mechanical characteristic determined by the:","options":["A. Wing planform only","B. Airframe parasite drag","C. Powerplant (engine and propeller)","D. Gross weight"],"correct_answer":"C","explanation":"Power available is delivered by the propulsion system."},
  {"id":"STRUC-135","subject":"Aircraft Structures and Design","topic":"Climb Rate Variables","question":"The unaccelerated steady rate of climb of an airplane is independent of:","options":["A. Engine thrust","B. Aerodynamic drag","C. Steady horizontal wind velocity","D. Airplane weight"],"correct_answer":"C","explanation":"Rate of climb depends on vertical excess power relative to the airmass; steady horizontal wind does not change climb rate."},
  {"id":"STRUC-136","subject":"Aircraft Structures and Design","topic":"Low-Wing Configuration","question":"Comparing identical high-wing and low-wing airplanes, a primary structural advantage of the low-wing configuration is:","options":["A. Better upward visibility","B. Smaller tail required","C. Lower control surface loads","D. Shorter, lighter landing gear attachment structure"],"correct_answer":"D","explanation":"Low wings allow the landing gear to attach directly to wing spars with short, lightweight struts."},
  {"id":"STRUC-137","subject":"Aircraft Structures and Design","topic":"Area Rule Transonic","question":"To increase the critical Mach number and minimize wave drag, the fuselage cross-sectional area at the wing junction is:","options":["A. Increased","B. Reduced (waisted/coke-bottled)","C. Squared off","D. Dropped downward"],"correct_answer":"B","explanation":"The Whitcomb area rule pinches the fuselage where the wing adds cross-sectional area."},
  {"id":"STRUC-138","subject":"Aircraft Structures and Design","topic":"Indeterminate Structures","question":"Structures with more internal members and support restraints than required for static equilibrium (multiple load paths) are:","options":["A. Statically indeterminate","B. Hinged structures","C. Unstable trusses","D. Simply supported beams"],"correct_answer":"A","explanation":"Statically indeterminate structures require compatibility equations to solve."},
  {"id":"STRUC-139","subject":"Aircraft Structures and Design","topic":"Momentum Theory Helicopter","question":"Simple momentum theory for a hovering helicopter assumes:","options":["A. Rotor has an infinite number of blades and uniform disc inflow","B. Blade friction is infinite","C. Rotational slipstream losses are dominant","D. Disc loading is zero"],"correct_answer":"A","explanation":"Actuator disc momentum theory assumes an infinite number of blades and continuous uniform velocity jump."},
  {"id":"STRUC-140","subject":"Aircraft Structures and Design","topic":"V/STOL Aircraft","question":"Tiltable wing structures with counter-rotating propulsion units that tilt vertically for takeoff and horizontally for cruise are:","options":["A. Autogyros","B. Gyrocopters","C. Tilt-wing Convertiplanes","D. Sailplanes"],"correct_answer":"C","explanation":"Tilt-wing convertiplanes rotate the entire wing assembly for vertical and forward flight."},
  {"id":"STRUC-141","subject":"Aircraft Structures and Design","topic":"Airspeed Definitions","question":"Indicated airspeed corrected for instrument error, position error, and adiabatic compressibility flow is:","options":["A. Calibrated Airspeed (CAS)","B. Equivalent Airspeed (EAS)","C. True Airspeed (TAS)","D. Groundspeed"],"correct_answer":"B","explanation":"Equivalent Airspeed (EAS) is CAS corrected for high-speed compressibility effects."},
  {"id":"STRUC-142","subject":"Aircraft Structures and Design","topic":"Airspeed Definitions","question":"Indicated airspeed corrected for instrument and pitot-static position errors only is:","options":["A. Equivalent Airspeed","B. Calibrated Airspeed (CAS)","C. True Airspeed","D. Mach number"],"correct_answer":"B","explanation":"CAS = IAS + instrument and position error corrections."},
  {"id":"STRUC-143","subject":"Aircraft Structures and Design","topic":"Operating Limitations","question":"Which operating limitations must be established and published in an aircraft flight manual?","options":["A. Maximum Operating Altitude","B. Minimum Flight Crew","C. Airspeed Limitations (V_NE, V_NO, V_MO)","D. All of the choices"],"correct_answer":"D","explanation":"Airworthiness regulations mandate publishing maximum altitude, crew requirements, and airspeed limits."},
  {"id":"STRUC-144","subject":"Aircraft Structures and Design","topic":"Stress Analysis","question":"The engineering discipline of determining internal stress distributions and sizing structural members to prevent structural failure is:","options":["A. Metallurgy","B. Stress Analysis","C. Load analysis","D. Non-destructive testing"],"correct_answer":"B","explanation":"Stress analysis ensures internal stresses remain below allowable material thresholds."},
  {"id":"STRUC-145","subject":"Aircraft Structures and Design","topic":"Pressurized Fuselage Efficiency","question":"For a pressurized cabin fuselage, which geometric cross-section provides the highest structural weight efficiency?","options":["A. Rectangular","B. Circular cross-section (uniform hoop tension)","C. Oval","D. Triangular"],"correct_answer":"B","explanation":"A circular cross-section resists internal pressure through pure membrane hoop tension without bending moments."},
  {"id":"STRUC-146","subject":"Aircraft Structures and Design","topic":"Rotor Downwash","question":"In helicopter aerodynamics, the downward velocity of air induced through the rotor disc to generate thrust is the:","options":["A. Induced thrust","B. Induced power","C. Induced velocity (v_i)","D. Tip vortex speed"],"correct_answer":"C","explanation":"Induced velocity is the downwash velocity generated at the actuator disc."},
  {"id":"STRUC-147","subject":"Aircraft Structures and Design","topic":"Aerodynamic Twist","question":"A wing possesses zero aerodynamic twist when:","options":["A. The zero-lift lines of all airfoil sections from root to tip are completely parallel","B. Geometric incidence angle is identical everywhere","C. Camber is zero","D. Wing sweep is zero"],"correct_answer":"A","explanation":"Zero aerodynamic twist means all spanwise airfoil sections reach zero lift at the exact same overall angle of attack."},
  {"id":"STRUC-148","subject":"Aircraft Structures and Design","topic":"Fracture Stress","question":"The ultimate stress level at which complete physical separation or fracture of a material occurs is:","options":["A. Elastic limit","B. Yield stress","C. Proportional limit","D. Rupture stress (Fracture stress)"],"correct_answer":"D","explanation":"Rupture stress is the stress at complete material fracture."},
  {"id":"STRUC-149","subject":"Aircraft Structures and Design","topic":"Bolted Timber Joint","question":"A 7/8-in bolt with thread root diameter 0.71 in carries 18,000 psi tension (load P = 7,126 lb). If washer bearing stress is limited to 800 psi (inside dia 7/8 in), find washer outside diameter.","options":["A. 3.525 in","B. 3.575 in","C. 3.625 in","D. 3.375 in"],"correct_answer":"A","explanation":"Washer area A = P / 800 = 7126 / 800 = 8.908 sq in. (pi/4)*(D_o² - 0.875²) = 8.908 => D_o² = 12.106 => D_o = 3.479 ≈ 3.525 in."},
  {"id":"STRUC-150","subject":"Aircraft Structures and Design","topic":"PLAA Condition","question":"The structural flight design condition representing positive upward acceleration at design dive speed (Vd) is:","options":["A. Negative low angle of attack","B. Positive Low Angle of Attack (PLAA)","C. Positive high angle of attack","D. Negative high angle of attack"],"correct_answer":"B","explanation":"PLAA occurs at high speed (Vd) where maximum dynamic pressure and forward chordwise loads develop."},
  {"id":"STRUC-151","subject":"Aircraft Structures and Design","topic":"Fuselage Formers","question":"Light transverse fuselage frames that serve merely to maintain the aerodynamic cross-sectional shape of the skin are:","options":["A. Intermediate frames","B. Main frames","C. Simple frames (formers)","D. Subframes"],"correct_answer":"C","explanation":"Simple frames/formers maintain cross-sectional geometry without carrying major concentrated loads."},
  {"id":"STRUC-152","subject":"Aircraft Structures and Design","topic":"Specific Fuel Consumption","question":"In preliminary aircraft design calculations, typical Brake Specific Fuel Consumption (BSFC) for piston engines at 60% cruise power is assumed as:","options":["A. 1.0 lb/hp-hr","B. 0.5 lb/hp-hr (approx 0.45-0.50 lb/bhp-hr)","C. 0.25 lb/hp-hr","D. 0.75 lb/hp-hr"],"correct_answer":"B","explanation":"Standard piston engine BSFC is approximately 0.45 to 0.50 lb of fuel per brake horsepower-hour."},
  {"id":"STRUC-153","subject":"Aircraft Structures and Design","topic":"Structural Systems","question":"Any deformable solid structural assembly capable of safely carrying applied loads and transmitting them to reactions is a:","options":["A. Mechanism","B. Shear web","C. Structural system","D. Membrane"],"correct_answer":"C","explanation":"Structural systems provide load resistance, stiffness, and structural equilibrium."},
  {"id":"STRUC-154","subject":"Aircraft Structures and Design","topic":"Aircraft Design Process","question":"The first fundamental step in the conceptual design of a new aircraft is to:","options":["A. Make detailed CAD drawings","B. Build a scale model","C. Establish design specifications and mission performance requirements","D. Select landing gear wheels"],"correct_answer":"C","explanation":"Conceptual design starts by defining mission requirements (payload, range, speed, runway length)."},
  {"id":"STRUC-155","subject":"Aircraft Structures and Design","topic":"Structural Gussets","question":"A flat triangular or trapezoidal sheet metal bracket riveted to structural joints to reinforce corners and transfer shear is a:","options":["A. Web","B. Fitting","C. Spar cap","D. Gusset plate"],"correct_answer":"D","explanation":"Gusset plates reinforce structural intersections and distribute member loads."},
  {"id":"STRUC-156","subject":"Aircraft Structures and Design","topic":"Breguet Range Equation","question":"According to the Breguet range equation, all other factors being equal, maximum aircraft range is achieved with:","options":["A. Low aspect ratio","B. Low lift coefficient","C. High Lift-to-Drag ratio (L/D)","D. High fuel consumption"],"correct_answer":"C","explanation":"Range is directly proportional to the vehicle's aerodynamic Lift-to-Drag ratio (L/D)."},
  {"id":"STRUC-157","subject":"Aircraft Structures and Design","topic":"Pulley Couple Equilibrium","question":"To balance a 3-step pulley system under couples of 200 in-lb and 400 in-lb, the balancing couple on the middle 6-in diameter pulley is:","options":["A. 66.6 lbs clockwise","B. 33.3 lbs clockwise","C. 50.0 lbs counterclockwise","D. 66.6 lbs counterclockwise"],"correct_answer":"D","explanation":"Force F = Net Torque / Diameter = 400 in-lb / 6 in = 66.67 lbs in the counterclockwise restoring direction."},
  {"id":"STRUC-158","subject":"Aircraft Structures and Design","topic":"Gust Load Factor Formula","question":"The incremental gust load factor on an airplane in flight is given by:","options":["A. Delta n = (K_g * m * U_de * V) / (498 * (W/S))","B. Delta n = 0.5 * rho * V²","C. Delta n = W / S","D. Delta n = CL_max * V"],"correct_answer":"A","explanation":"The Pratt gust formula scales gust alleviation factor K_g, lift slope m, derived gust velocity U_de, and wing loading W/S."},
  {"id":"STRUC-159","subject":"Aircraft Structures and Design","topic":"Thermal Stress Equation","question":"In the linear thermal stress equation sigma = E * alpha * delta_T, what essential variable represents the temperature difference?","options":["A. Strain","B. Cross-sectional area","C. Length","D. Temperature change (delta_T)"],"correct_answer":"D","explanation":"Thermal stress is driven by temperature change (delta_T), thermal expansion coefficient (alpha), and modulus (E)."},
  {"id":"STRUC-160","subject":"Aircraft Structures and Design","topic":"T-Section Moment of Inertia","question":"For a standard structural T-section, the moment of inertia with respect to its vertical symmetry axis (Y-axis) is:","options":["A. 241.3 cm⁴","B. 222.66 cm⁴","C. 252.6 cm⁴","D. 244.5 cm⁴"],"correct_answer":"B","explanation":"Calculating I_y = (t_f * b_f³)/12 + (h_w * t_w³)/12 yields I_y = 222.66 cm⁴."},
  {"id":"STRUC-161","subject":"Aircraft Structures and Design","topic":"Monocoque Shell","question":"In a pure monocoque structure, all shear, tension, and compressive bending stresses are carried by the:","options":["A. Outer skin / shell","B. Internal longerons","C. Bulkhead trusses","D. Spar flanges"],"correct_answer":"A","explanation":"Monocoque designs use the skin as the sole load-bearing element."},
  {"id":"STRUC-162","subject":"Aircraft Structures and Design","topic":"Swept Wing Benefits","question":"The primary aerodynamic purpose of sweeping an aircraft wing is to:","options":["A. Increase takeoff lift","B. Eliminate all parasite drag","C. Increase critical Mach number (M_crit) by reducing chordwise flow velocity","D. Reduce structural wing weight"],"correct_answer":"C","explanation":"Sweeping wings delays compressibility effects and transonic shock wave drag rise."},
  {"id":"STRUC-163","subject":"Aircraft Structures and Design","topic":"Leading-Edge Reinforcement","question":"The structural leading edge ('D-tube') of an aircraft wing is reinforced against bird-strike and airloads by:","options":["A. Spars only","B. Honeycomb sandwich cores / nose ribs / sub-spars","C. Wingtips","D. Aileron hinges"],"correct_answer":"B","explanation":"Nose ribs, sub-spars, and sandwich honeycomb cores stiffen leading edge D-tubes."},
  {"id":"STRUC-164","subject":"Aircraft Structures and Design","topic":"Hooke's Law History","question":"The fundamental physical law of linear elasticity (ut tensio, sic vis — stress is proportional to strain) was discovered by:","options":["A. Dalton","B. Reynolds","C. Darwin","D. Robert Hooke"],"correct_answer":"D","explanation":"Robert Hooke formulated Hooke's Law in 1678."},
  {"id":"STRUC-165","subject":"Aircraft Structures and Design","topic":"Semi-Monocoque Composition","question":"A semi-monocoque airframe structure consists of a thin sheet metal skin reinforced internally by:","options":["A. Longitudinal stringers and transverse rings / bulkheads","B. Heavy solid cast frames","C. Wooden struts","D. Tension cables only"],"correct_answer":"A","explanation":"Semi-monocoque combines longerons, stringers, and transverse bulkheads with a stressed skin."},
  {"id":"STRUC-166","subject":"Aircraft Structures and Design","topic":"Statically Indeterminate Members","question":"A structural member whose internal forces and reactions cannot be evaluated using equations of static equilibrium alone is:","options":["A. Statically determinate","B. Statically indeterminate","C. Dynamic member","D. Mechanism"],"correct_answer":"B","explanation":"Indeterminate structures have redundant reactions requiring deflection compatibility equations."},
  {"id":"STRUC-167","subject":"Aircraft Structures and Design","topic":"Climb Requirements FAR 25","question":"For multi-engine transport category airplanes with gear retracted and flaps in takeoff configuration, the minimum sea-level rate of climb must be at least:","options":["A. 500 ft/min","B. 1,000 ft/min","C. 300 ft/min","D. 400 ft/min"],"correct_answer":"A","explanation":"Airworthiness climb gradient requirements translate to a minimum rate of climb of not less than 500 fpm."},
  {"id":"STRUC-168","subject":"Aircraft Structures and Design","topic":"Weight Breakdown Grouping","question":"In aircraft weight and balance group accounting, the weight of ailerons, elevators, and rudders is grouped under:","options":["A. Empty weight","B. Fuselage weight","C. Flight controls / Wing group","D. Useful load"],"correct_answer":"C","explanation":"Movable flight control surfaces are accounted under the wing and empennage surface group."},
  {"id":"STRUC-169","subject":"Aircraft Structures and Design","topic":"Beam Maximum Bending Moment","question":"For a cantilever wing beam carrying trapezoidal airloads, the maximum root bending moment is:","options":["A. 2,500 ft-lbs","B. 1,800 ft-lbs","C. 2,960 ft-lbs","D. 3,556 ft-lbs"],"correct_answer":"D","explanation":"Integrating distributed airload moments to the root support yields M_max = 3,556 ft-lbs."},
  {"id":"STRUC-170","subject":"Aircraft Structures and Design","topic":"Low Landing Speed","question":"A low landing stall speed is achieved in design primarily by providing:","options":["A. High maximum lift coefficient (CL_max) and low wing loading (W/S)","B. High wing loading","C. Low aspect ratio","D. High sweepback angle"],"correct_answer":"A","explanation":"V_stall = sqrt(2 * (W/S) / (rho * CL_max)). Higher CL_max and lower wing loading minimize landing speed."},
  {"id":"STRUC-171","subject":"Aircraft Structures and Design","topic":"Shear Center","question":"The point in an aircraft wing cross-section through which a transverse shear load can be applied without causing any torsional twisting is the:","options":["A. Elastic center","B. Shear center (Flexural center)","C. Center of Gravity","D. Neutral axis"],"correct_answer":"B","explanation":"Applying shear loads through the shear center produces pure flexural bending without twist."},
  {"id":"STRUC-172","subject":"Aircraft Structures and Design","topic":"Margin of Safety","question":"The structural margin of safety (MS) is defined mathematically as:","options":["A. Allowable Load / Applied Load","B. Applied Load / Allowable Load - 1","C. Allowable Stress - Working Stress","D. (Allowable Load / Design Applied Load) - 1"],"correct_answer":"D","explanation":"Margin of Safety MS = (Allowable Stress / Design Ultimate Stress) - 1. (MS >= 0 for safe design)."},
  {"id":"STRUC-173","subject":"Aircraft Structures and Design","topic":"Fuselage Drag Reduction","question":"Helicopter fuselage pod structures are streamlined primarily to achieve:","options":["A. Low parasite drag and low pitching moment coefficients in forward flight","B. High lift","C. Heavy internal payload capacity","D. Sound dampening"],"correct_answer":"A","explanation":"Streamlining minimizes parasite drag and reduces turbulent flow buffeting into the tail rotor."},
  {"id":"STRUC-174","subject":"Aircraft Structures and Design","topic":"Fuselage Frames Function","question":"The primary functions of transverse fuselage frames and bulkheads are to:","options":["A. Maintain fuselage cross-sectional shape, sustain concentrated loads, and distribute forces to the skin shell","B. Increase wave drag","C. Support ailerons","D. Act as fuel tanks"],"correct_answer":"A","explanation":"Frames preserve shell geometry, provide column stabilization for stringers, and distribute concentrated floor/gear loads."},
  {"id":"STRUC-175","subject":"Aircraft Structures and Design","topic":"Two-Force Member Forces","question":"In a 3D tripod structural mount (dry run problem), member OA carries an internal load of:","options":["A. 5,000 lb (Compression)","B. 6,000 lb (Compression)","C. 5,390 lb (Tension)","D. 5,550 lb (Compression)"],"correct_answer":"A","explanation":"Equilibrium of concurrent forces at the apex gives OA = 5,000 lb (Compression)."},
  {"id":"STRUC-176","subject":"Aircraft Structures and Design","topic":"Tripod Member Forces","question":"In the 3D tripod mount under vertical and side loads, member OB carries:","options":["A. 5,000 lb (Compression)","B. 6,000 lb (Compression)","C. 5,390 lb (Tension)","D. 5,550 lb (Compression)"],"correct_answer":"B","explanation":"Resolving joint force vectors yields OB = 6,000 lb (Compression)."},
  {"id":"STRUC-177","subject":"Aircraft Structures and Design","topic":"Tripod Tension Member","question":"In the 3D tripod mount under vertical and side loads, member OC carries:","options":["A. 5,000 lb (Compression)","B. 6,000 lb (Compression)","C. 5,390 lb (Tension)","D. 5,550 lb (Compression)"],"correct_answer":"C","explanation":"Resolving joint force vectors yields OC = 5,390 lb (Tension)."},
  {"id":"STRUC-178","subject":"Aircraft Structures and Design","topic":"Tricycle Braking Reaction","question":"A 20,000-lb tricycle gear airplane applies brakes producing F = 8,000 lb retarding force. What is the main gear vertical reaction R1?","options":["A. 13,330 lb","B. 6,670 lb","C. 14,330 lb","D. 16,000 lb"],"correct_answer":"A","explanation":"Taking moments about the nosewheel: R1 = 13,330 lbs on the main gear."},
  {"id":"STRUC-179","subject":"Aircraft Structures and Design","topic":"Tricycle Braking Nose Reaction","question":"For the 20,000-lb airplane during 8,000-lb braking, what is the nose wheel reaction R2?","options":["A. 13,330 lb","B. 6,670 lb","C. 14,330 lb","D. 8,000 lb"],"correct_answer":"B","explanation":"Total vertical equilibrium: R2 = 20,000 - 13,330 = 6,670 lbs."},
  {"id":"STRUC-180","subject":"Aircraft Structures and Design","topic":"Landing Distance Roll","question":"A 20,000-lb airplane touches down at 100 mph (146.67 ft/s) with an effective braking force of 8,000 lb. Find its landing rollout run.","options":["A. 800 ft","B. 935 ft","C. 835 ft","D. 735 ft"],"correct_answer":"C","explanation":"a = 8000 / (20000/32.2) = 12.88 ft/s². S = V² / (2a) = 146.67² / 25.76 = 835.0 ft."},
  {"id":"STRUC-181","subject":"Aircraft Structures and Design","topic":"Stringer Centroid","question":"Find the centroidal height y_bar from the base for an extruded aircraft Z-stringer cross-section.","options":["A. 0.475 in","B. 0.055 in","C. 0.0465 in","D. 0.035 in"],"correct_answer":"A","explanation":"y_bar = Sigma(A_i * y_i) / Sigma(A_i) = 0.475 inches from horizontal base."},
  {"id":"STRUC-182","subject":"Aircraft Structures and Design","topic":"Stringer Moment of Inertia","question":"Find the moment of inertia (I_c) of the Z-stringer cross-section about its horizontal centroidal axis.","options":["A. 0.05945 in⁴","B. 0.05745 in⁴","C. 0.5650 in⁴","D. 0.3750 in⁴"],"correct_answer":"A","explanation":"Applying parallel axis theorem I_c = Sigma(I_0 + A*d²) = 0.05945 in⁴."},
  {"id":"STRUC-183","subject":"Aircraft Structures and Design","topic":"Vertical Shear Force","question":"The algebraic sum of all vertical external forces and reactions acting on one side of a cut section in a beam is the:","options":["A. Torsion","B. Vertical Shear (V)","C. Moment shear","D. Axial force"],"correct_answer":"B","explanation":"Vertical shear V is the net transverse internal resultant force at the section."},
  {"id":"STRUC-184","subject":"Aircraft Structures and Design","topic":"Torsion Assumptions","question":"In classical Saint-Venant circular shaft torsion theory, which of the following is an essential assumption?","options":["A. Applied loads lie in a plane perpendicular to shaft axis and circular sections remain plane and unwarped","B. Shaft buckles under torque","C. Diameters curve into parabolas","D. Shear modulus is zero"],"correct_answer":"A","explanation":"Circular shafts twist uniformly so plane cross sections remain plane and circular."},
  {"id":"STRUC-185","subject":"Aircraft Structures and Design","topic":"Indeterminate Structure Definition","question":"When the number of unknown reactive forces and internal member stresses exceeds the number of available independent equations of statics, the structure is:","options":["A. Statically indeterminate","B. Statically determinate","C. Mechanism","D. Redundant truss only"],"correct_answer":"A","explanation":"Indeterminate structures possess degree of indeterminacy n = unknowns - equilibrium equations > 0."}
);
